# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "forwarded Timekeeping setup helpers" do
  let(:arrange_company) { create(:company) }
  let(:arrange_actor) { create(:user, current_workspace_id: arrange_company.id) }
  let(:arrange_paul) do
    create(:user, first_name: "Paul", last_name: "Connors", email: "arrange-paul@example.com",
                  current_workspace_id: arrange_company.id)
  end
  let(:arrange_project) do
    create(:project, name: "Website", billable: true, client: create(:client, company: arrange_company, name: "Acme LLC"))
  end
  let(:arrange_fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  # The copied setups every forwarded group used set the ownership singleton to owner
  # "timekeeping" at generation 2, gave the fake the same generation, registered the company,
  # the admin actor, paul and the project, and routed HTTP to the fake. The shared helper must
  # keep all of them, or forwarded imports in the migrated groups stop reaching the fake.
  # What a forwarded import then sends is checked by the importer and job specs, not here.
  it "arrange_forwarded_timekeeping hands ownership to the fake at generation 2 and routes Timekeeping HTTP to it" do
    %i[register_company register_user register_project].each do |method|
      allow(arrange_fake).to receive(method).and_call_original
    end
    allow(self).to receive(:route_timekeeping_to_fake).and_call_original

    arrange_forwarded_timekeeping(arrange_fake, company: arrange_company,
                                                users: { arrange_actor => "admin", arrange_paul => "employee" },
                                                project: arrange_project)

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "timekeeping", generation: 2)
    expect(arrange_fake.generation).to eq(2)
    expect(arrange_fake).to have_received(:register_company)
      .once.with(id: arrange_company.id, edit_days: arrange_company.timesheet_edit_days)
    expect(arrange_fake).to have_received(:register_user).twice
    expect(arrange_fake).to have_received(:register_user).with(id: arrange_actor.id, company_id: arrange_company.id, role: "admin")
    expect(arrange_fake).to have_received(:register_user).with(id: arrange_paul.id, company_id: arrange_company.id, role: "employee")
    expect(arrange_fake).to have_received(:register_project).once.with(id: arrange_project.id, company_id: arrange_company.id)
    expect(self).to have_received(:route_timekeeping_to_fake).once.with(arrange_fake, base_url: FORWARDED_TIMEKEEPING_BASE_URL)
  end

  # Every copied setup this helper replaces set owner "timekeeping" with generation 2 on the ownership row
  # and on the fake, so a generation-bump example that starts from a leftover generation would not bump past it.
  it "resets ownership to timekeeping at generation 2 on both sides even when an earlier step left a later generation" do
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).update_columns(owner: "monolith", generation: 7)
    arrange_fake.generation = 7
    allow(arrange_fake).to receive(:register_user).and_call_original

    arrange_forwarded_timekeeping(arrange_fake, company: arrange_company,
                                                users: { arrange_paul => "employee" },
                                                project: arrange_project)

    ownership = TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
    expect(ownership).to have_attributes(owner: "timekeeping", generation: 2)
    expect(arrange_fake.generation).to eq(2)
    # Only the users passed in are registered, so a spec whose actor has left the company can leave it out.
    expect(arrange_fake).to have_received(:register_user).once
    expect(arrange_fake).to have_received(:register_user).with(id: arrange_paul.id, company_id: arrange_company.id, role: "employee")
  end
end

RSpec.describe "forwarded Timekeeping environment helper" do
  # Both variables must be set for a forwarded import: the base URL picks the service and the key
  # signs the user token. A helper that set only one, or leaked them past the block, would break
  # other examples that expect the legacy store.
  it "with_forwarded_timekeeping_env sets the base URL and signing key inside the block and restores both afterwards" do
    base_url_env = Timekeeping::EntryApiClient::BASE_URL_ENV
    key_env = Timekeeping::UserToken::PRIVATE_KEY_ENV
    previous = { base_url_env => ENV.fetch(base_url_env, nil), key_env => ENV.fetch(key_env, nil) }
    seen = nil

    with_forwarded_timekeeping_env do
      seen = { base_url_env => ENV.fetch(base_url_env, nil), key_env => ENV.fetch(key_env, nil) }
    end

    expect(FORWARDED_TIMEKEEPING_BASE_URL).to eq("http://timekeeping.test")
    expect(seen[base_url_env]).to eq("http://timekeeping.test")
    expect(seen[key_env]).to eq(timekeeping_key_pair.to_pem)
    expect(ENV.fetch(base_url_env, nil)).to eq(previous[base_url_env])
    expect(ENV.fetch(key_env, nil)).to eq(previous[key_env])

    with_forwarded_timekeeping_env("http://other-timekeeping.test") do
      expect(ENV.fetch(base_url_env, nil)).to eq("http://other-timekeeping.test")
    end
    expect(ENV.fetch(base_url_env, nil)).to eq(previous[base_url_env])
  end

  # An import that raises StaleGeneration or OwnershipMoving inside the block must not leave the
  # private key or base URL set for the next example, or later legacy examples would forward by accident.
  it "puts both Timekeeping environment variables back when the forwarded block raises" do
    with_timekeeping_env(
      Timekeeping::UserToken::PRIVATE_KEY_ENV => "outer-key",
      Timekeeping::EntryApiClient::BASE_URL_ENV => "http://outer.test"
    ) do
      seen = {}
      expect do
        with_forwarded_timekeeping_env do
          seen[:base_url] = ENV.fetch(Timekeeping::EntryApiClient::BASE_URL_ENV, nil)
          seen[:private_key] = ENV.fetch(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil)
          raise Timekeeping::Gateway::StaleGeneration
        end
      end.to raise_error(Timekeeping::Gateway::StaleGeneration)

      expect(seen).to eq(base_url: "http://timekeeping.test", private_key: timekeeping_key_pair.to_pem)
      expect(ENV.fetch(Timekeeping::EntryApiClient::BASE_URL_ENV, nil)).to eq("http://outer.test")
      expect(ENV.fetch(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil)).to eq("outer-key")
    end
  end
end
